-- Metadata-only schema snapshot for isolated SQL regression tests.
create table private.myday_ai_cache("owner_id" uuid,"kind" text,"fingerprint" text,"output" text,"created_at" timestamp with time zone);
create table private.myday_assignments("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"creator_id" uuid,"recipient_id" uuid,"source_task" uuid,"recipient_task" uuid,"title" text,"details" text,"due_date" date,"status" text,"suggested_date" date,"nudged_at" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
create table private.myday_comments("id" uuid primary key default gen_random_uuid(),"task_id" uuid,"company_id" uuid,"author_id" uuid,"body" text,"private_note" boolean,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
create table private.myday_competition("company_id" uuid,"mode" text,"updated_at" timestamp with time zone);
create table private.myday_notifications("id" uuid primary key default gen_random_uuid(),"owner_id" uuid,"company_id" uuid,"task_id" uuid,"assignment_id" uuid,"title" text,"body" text,"read_at" timestamp with time zone,"created_at" timestamp with time zone,"source_alert_id" uuid,"source_chat_message" uuid,"push_path" text);
create table private.myday_personal_options("owner_id" uuid primary key,"company_id" uuid,"settings" jsonb,"calendar_hash" text,"calendar_enabled" boolean);
create table private.myday_repeats("id" uuid primary key default gen_random_uuid(),"owner_id" uuid,"company_id" uuid,"task_id" uuid,"current_task" uuid,"frequency" text,"every_n" integer,"unit" text,"anchor" date,"next_date" date,"active" boolean,"template" jsonb,"created_at" timestamp with time zone);
create table private.myday_rules("id" uuid primary key default gen_random_uuid(),"owner_id" uuid,"company_id" uuid,"shared" boolean,"title" text,"trigger_event" text,"source_type" text,"after_days" integer,"effects" jsonb,"enabled" boolean,"created_at" timestamp with time zone);
create table private.myday_star_awards("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"owner_id" uuid,"task_id" uuid,"day" date,"points" integer,"reason" text,"source_key" text,"voided" boolean,"created_at" timestamp with time zone,"credit_units" integer);
create table private.myday_star_consent("owner_id" uuid,"company_id" uuid,"visible" boolean,"updated_at" timestamp with time zone);
create table private.myday_streak_pauses("owner_id" uuid,"starts_on" date,"ends_on" date);
create table private.myday_streak_settings("owner_id" uuid primary key,"company_id" uuid,"days" integer[]);
create table private.myday_templates("id" uuid primary key default gen_random_uuid(),"owner_id" uuid,"company_id" uuid,"shared" boolean,"title" text,"data" jsonb,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
create table public.actions("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"owner_id" uuid,"decision_id" uuid,"title" text,"details" text,"due_date" date,"status" text,"source_url" text,"completion_note" text,"completed_at" timestamp with time zone,"deleted_at" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"department_id" uuid,"external_contact_id" uuid,"source_kind" text,"due_time" time without time zone,"due_at" timestamp with time zone,"remind_at" timestamp with time zone,"reminder_option" text,"reminder_sent_at" timestamp with time zone,"check_in_sent_at" timestamp with time zone,"overdue" boolean,"reminder_cycle" integer,"recurring_id" uuid,"recurring_date" date,"context_kind" text,"context_record_id" uuid,"context_added_at" timestamp with time zone,"priority" text,"pinned_at" timestamp with time zone,"source_role_id" uuid,"capture_id" uuid,"capture_record_id" uuid,"stable_role_item_id" uuid,"repeat_rule" jsonb,"time_needed_minutes" integer,"steps" jsonb,"links" jsonb,"label" text,"created_by_ai" boolean,"deleted_by" uuid,"source_excerpt" text,"source_disconnected" boolean,"metadata" jsonb,"missed_at" timestamp with time zone,"purged_at" timestamp with time zone);
create table public.capture_items("id" uuid primary key default gen_random_uuid(),"capture_id" uuid,"owner_id" uuid,"company_id" uuid,"kind" text,"payload" jsonb,"status" text,"origin" text,"version" integer,"decision_id" uuid,"action_id" uuid,"contact_id" uuid,"created_at" timestamp with time zone,"reviewed_at" timestamp with time zone,"summary_id" uuid,"assignment_id" uuid);
create table public.captures("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"owner_id" uuid,"title" text,"source_text" text,"source_type" text,"source_date" date,"deleted_at" timestamp with time zone,"created_at" timestamp with time zone,"channel" text,"status" text,"file_reference" text,"sender" text,"error" text,"fingerprint" text,"record_id" uuid,"department_id" uuid,"draft_attempts" integer,"opened_at" timestamp with time zone,"role_profile_id" uuid,"source_fingerprint" text,"source_provider" text,"source_updated_at" timestamp with time zone,"source_account" uuid,"source_reference" text,"source_url" text,"label" text,"result_state" text,"trashed_at" timestamp with time zone);
create table public.companies("id" uuid primary key default gen_random_uuid(),"name" text,"contact_email" text,"team_mode" text,"created_by" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"logo_path" text);
create table public.console_support_tickets("id" uuid primary key default gen_random_uuid(),"ticket_number" bigint,"company_id" uuid,"company_name" text,"customer_user_id" uuid,"customer_name" text,"customer_email" text,"subject" text,"category" text,"priority" text,"status" text,"assigned_staff" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"first_reply_at" timestamp with time zone,"tags" text[]);
create table public.console_ticket_messages("id" uuid primary key default gen_random_uuid(),"ticket_id" uuid,"sender_kind" text,"sender_staff" uuid,"body" text,"created_at" timestamp with time zone,"request_id" uuid);
create table public.decisions("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"owner_id" uuid,"workstream_id" uuid,"title" text,"reason" text,"decided_by" text,"decided_on" date,"status" text,"source_url" text,"related_task_url" text,"deleted_at" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"next_step" text,"capture_id" uuid,"role_id" uuid,"role_fields" jsonb,"reviewed_at" timestamp with time zone,"replaces_id" uuid,"replaced_by_id" uuid);
create table public.departments("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"name" text,"manager_id" uuid,"created_at" timestamp with time zone,"archived_at" timestamp with time zone);
create table public.profiles("id" uuid primary key default gen_random_uuid(),"company_id" uuid,"full_name" text,"email" text,"role" text,"department_id" uuid,"active" boolean,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"role_description" text,"role_start_date" date,"employment_status" text);
create table public.work_preferences("owner_id" uuid primary key,"company_id" uuid,"timezone" text,"reminder_time" time without time zone,"email_enabled" boolean);
